function loadScript(url, callback)
{
    // adding the script element to the head
   var head = document.getElementsByTagName('head')[0];
   var script = document.createElement('script');
   script.type = 'text/javascript';
   script.src = url;

   // then bind the event to the callback function
   // there are several events for cross browser compatibility
   script.onreadystatechange = callback;
   script.onload = callback;

   // fire the loading
   head.appendChild(script);
}

const myProjectScriptCode = function() {
  let rng = new Stitch.Math.Random(tokenData.hash);

  // params
  let [wPx, hPx] = [1000, 1000];
  let widthMm = Stitch.Math.Utils.inToMm(5);
  let pixelsPerMm = wPx / widthMm;
  let shapeStitchLengthMm = 3;
  let shapeSeedResampleLengthMm = 2;
  let minConnectingStitchLengthMm = 2;
  let maxConnectingStitchLengthMm = 5;
  let maxJoinDistanceMm = 12;
  let stitchDensityCutoff = 4;
  let segmentDensityCutoff = 6;
  let nudgeAmountPx = 20;
  let svgMarginMultiplier = 0.05;

  function weightedRandomChoice(list) {
    let total = list.reduce((sum, current) => sum + current[0], 0);
    let [rnd, sum] = [rng.random_num(0, total), 0];
    for (let choice of list) {
      if (rnd < choice[0] + sum) return choice[1];
      else sum += choice[0];
    }
  }

  // features
  let palettes = [
    [0.5, 'black on white'],
    [0.5, 'white on black']
  ];
  let shapeStrategies = [
    [0.7, 'circle packing'],
    [0.3, 'lines']
  ];
  let patchCounts = [
    [0.3, 1],
    [0.3, 2],
    [0.3, 3],
    [0.07, 4],
    [0.03, 5],
  ];
  let palette = weightedRandomChoice(palettes);
  let shapeStrategy = weightedRandomChoice(shapeStrategies);
  let patchCount = weightedRandomChoice(patchCounts);
  // check url for overrides
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.has('widthMm')) [widthMm, pixelsPerMm] = [Number(urlParams.get('widthMm')), wPx / Number(urlParams.get('widthMm'))];
  if (urlParams.has('shapeStitchLengthMm')) shapeStitchLengthMm = Number(urlParams.get('shapeStitchLengthMm'));
  if (urlParams.has('shapeSeedResampleLengthMm')) shapeSeedResampleLengthMm = Number(urlParams.get('shapeSeedResampleLengthMm'));
  if (urlParams.has('minConnectingStitchLengthMm')) minConnectingStitchLengthMm = Number(urlParams.get('minConnectingStitchLengthMm'));
  if (urlParams.has('maxConnectingStitchLengthMm')) maxConnectingStitchLengthMm = Number(urlParams.get('maxConnectingStitchLengthMm'));
  if (urlParams.has('maxJoinDistanceMm')) maxJoinDistanceMm = Number(urlParams.get('maxJoinDistanceMm'));
  if (urlParams.has('stitchDensityCutoff')) stitchDensityCutoff = Number(urlParams.get('stitchDensityCutoff'));
  if (urlParams.has('segmentDensityCutoff')) segmentDensityCutoff = Number(urlParams.get('segmentDensityCutoff'));
  if (urlParams.has('svgMarginMultiplier')) svgMarginMultiplier = Number(urlParams.get('svgMarginMultiplier'));

  class DT {
    constructor(width, height) {
      this.width = width;
      this.height = height;
      let center = new Stitch.Math.Vector(0.5 * width, 0.5 * height);
      let radius = center.distance(new Stitch.Math.Vector(width, height));
      this.vs = [
        center.add(new Stitch.Math.Vector(-1 * Math.sqrt(3) * radius, -1 * radius)),
        center.add(new Stitch.Math.Vector(Math.sqrt(3) * radius, -1 * radius)),
        center.add(new Stitch.Math.Vector(0, 2 * radius))
      ];
      this.ts = [this.makeTriangle(0, 1, 2)];
    }
    add(x, y) {
      if (x < 0 || y < 0 || x > this.w || y > this.h) return;
      this.vs.push(new Stitch.Math.Vector(x, y));
      let nextTris = [];
      let newTris = [];
      for (let i = 0; i < this.ts.length; i++) {
        if (Stitch.Math.Utils.distance(x, y, this.ts[i].cc.x, this.ts[i].cc.y) < this.ts[i].cc.r) {
          newTris = newTris.concat(this.divTri(this.ts[i], this.vs.length - 1));
        } else {
          nextTris.push(this.ts[i]);
        }
      }
      for (let i = 0; i < newTris.length; i++) {
        let isBad = false;
        for (let j = 0; j < this.vs.length; j++) {
          if (this.isBadTri(newTris[i], j)) {
            isBad = true;
            break;
          }
        }
        if (!isBad) {
          nextTris.push(newTris[i]);
        }
      }
      this.ts = nextTris;
    }
    makeTriangle(i1, i2, i3) {
      function sq(v) { return v * v; }
      let t = {"a": i1, "b": i2, "c": i3};
      let v1 = this.vs[i1];
      let v2 = this.vs[i2];
      let v3 = this.vs[i3];
      if ((v2.x - v1.x) * (v3.y - v2.y) - (v3.x - v2.x) * (v2.y - v1.y) < 0) {
        t.b = i3;
        t.c = i2;
      }
      let c = 2 * ((v2.x - v1.x) * (v3.y - v1.y) - (v2.y - v1.y) * (v3.x - v1.x));
      let ccx = ((v3.y - v1.y) * (sq(v2.x) - sq(v1.x) + sq(v2.y) - sq(v1.y)) + (v1.y - v2.y) * (sq(v3.x) - sq(v1.x) + sq(v3.y) - sq(v1.y))) / c;
      let ccy = ((v1.x - v3.x) * (sq(v2.x) - sq(v1.x) + sq(v2.y) - sq(v1.y)) + (v2.x - v1.x) * (sq(v3.x) - sq(v1.x) + sq(v3.y) - sq(v1.y))) / c;
      t.cc = {"x": ccx, "y": ccy, "r": v1.distance(new Stitch.Math.Vector(ccx, ccy))};
      return t;
    }
    divTri(t, i) { return [this.makeTriangle(t.a, t.b, i), this.makeTriangle(t.b, t.c, i), this.makeTriangle(t.c, t.a, i)]; }
    isBadTri(t, i) {
      if (t.a == i || t.b == i || t.c == i) return false;
      else return Stitch.Math.Utils.distance(this.vs[i].x, this.vs[i].y, t.cc.x, t.cc.y) < t.cc.r;
    }
  }

  class Cmplx {
    constructor(a, b) { [this.re, this.im] = [a, b]; }
    add(c) { return new Cmplx(this.re + c.re, this.im + c.im); }
    sub(c) { return new Cmplx(this.re - c.re, this.im - c.im); }
    multRe(r) { return new Cmplx(this.re * r, this.im * r); }
    divRe(r) { return new Cmplx(this.re / r, this.im / r); }
    mult(c) { return new Cmplx(this.re * c.re - this.im * c.im, this.re * c.im + this.im * c.re); }
  }

  class CP {
    constructor(dt, rf = function(){ return random(10, 20); }, e = 1.0000000000001) {
      this.dt = dt;
      [this.int, this.ext] = this.getIntExt(dt, rf);
      if (Object.keys(this.int).length > 0) this.pack(e);
      this.ts = [];
    }
    getIntExt(dt, rf) {
      // a mapping from all interior circles to their neighbors
      let int = {};
      // a mapping from all exterior circles to their target radius
      let ext = {};
      // get rid of first 3 points in the delaunay triangulation
      dt.vs.splice(0, 3);
      for (let i = dt.ts.length - 1; i >= 0; i--) {
        let t = dt.ts[i];
        if (t.a > 2 && t.b > 2 && t.c > 2) {
          // adjust the index because we deleted the first 3 points
          t.a -= 3;
          t.b -= 3;
          t.c -= 3;
        } else {
          // add placeholder for the target radius of exterior circles
          if (t.a > 2) ext[t.a - 3] = rf();
          if (t.b > 2) ext[t.b - 3] = rf();
          if (t.c > 2) ext[t.c - 3] = rf();
          // remove any triangles that contained any of the first 3 points
          dt.ts.splice(i, 1);
        }
      }
      // set up the neighbor mapping for interior circles
      for (let i = 0; i < dt.ts.length; i++) {
        let t = dt.ts[i];
        if (!(t.a in int)) int[t.a] = new Set([t.b, t.c]);
        else [t.b, t.c].forEach(int[t.a].add, int[t.a]);
        if (!(t.b in int)) int[t.b] = new Set([t.a, t.c]);
        else [t.a, t.c].forEach(int[t.b].add, int[t.b]);
        if (!(t.c in int)) int[t.c] = new Set([t.a, t.b]);
        else [t.a, t.b].forEach(int[t.c].add, int[t.c]);
      }
      // convert to array and sort the neighbors counter-clockwise
      for (let [k, v] of Object.entries(int)) {
        int[k] = Array.from(v).sort((a, b) => Math.atan2(dt.vs[a].y - dt.vs[k].y, dt.vs[a].x - dt.vs[k].x) - Math.atan2(dt.vs[b].y - dt.vs[k].y, dt.vs[b].x - dt.vs[k].x));
      }
      // make sure there are no external points in the internal keys
      for (let [k, v] of Object.entries(ext)) delete int[k];
      return [int, ext];
    }
    pack(e) {
      this.r = {};
      this.pl = {};
      this.pck = {};
      for (let [k, v] of Object.entries(this.ext)) this.r[k] = v;
      for (let [k, v] of Object.entries(this.int)) this.r[k] = 1;
      let lc = 2;
      let cnt = 0;
      while (lc > e && cnt < 50000) {
        lc = 1;
        for (let [k, v] of Object.entries(this.int)) {
          let th = this.flower(k, v);
          let hat = this.r[k] / (1 / Math.sin(th / (2 * v.length)) - 1);
          let newRad = hat * (1 / (Math.sin(Math.PI / v.length)) - 1);
          let kc = Math.max(newRad / this.r[k], this.r[k] / newRad);
          this.r[k] = newRad;
          lc = Math.max(lc, kc);
        }
        cnt++;
      }
      let k1 = Object.keys(this.int)[0];
      this.pl[k1] = new Cmplx(0, 0);
      let k2 = this.int[k1][0];
      this.pl[k2] = new Cmplx(this.r[k1] + this.r[k2], 0);
      this.place(k1);
      this.place(k2);
      for (let [k, v] of Object.entries(this.int)) {
        if (k in this.pl) this.pck[k] = {"x": this.pl[k].re, "y": this.pl[k].im, "r": this.r[k], "l": "interior"};
      }
      for (let [k, v] of Object.entries(this.ext)) {
        if (k in this.pl) this.pck[k] = {"x": this.pl[k].re, "y": this.pl[k].im, "r": this.r[k], "l": "exterior"};
      }
    }
    flower(cen, cyc) {
      let s = 0;
      for (let i = 0; i < cyc.length; i++) s += this.acxyz(this.r[cen], this.r[cyc[i]], this.r[cyc[(i + 1) % cyc.length]]);
      return s;
    }
    acxyz(x, y, z) {
      let a = (Math.pow(x + y, 2) + Math.pow(x + z, 2) - Math.pow(y + z, 2)) / (2.0 * (x + y) * (x + z));
      if (x + y == 0 || x + z == 0) return PI;
      else if (Math.abs(a) > 1) return PI / 3.0;
      else return Math.acos(a);
    }
    place(idx) {
      if (idx in this.int) {
        let cyc = this.int[idx];
        for (let i = 0; i < 2 * cyc.length - 1; i++) {
          if (cyc[i % cyc.length] in this.pl && !(cyc[(i + 1) % cyc.length] in this.pl)) {
            let s = cyc[i % cyc.length];
            let t = cyc[(i + 1) % cyc.length];
            let th = this.acxyz(this.r[idx], this.r[s], this.r[t]);
            let offset = this.pl[s].sub(this.pl[idx]).divRe(this.r[s] + this.r[idx]).mult(new Cmplx(Math.cos(-th), Math.sin(-th)));
            this.pl[t] = this.pl[idx].add(offset.multRe(this.r[t] + this.r[idx]));
            this.place(t);
          }
        }
      }
    }
    resize(x, y, w, h) {
      let optimalAngle = 0;
      let optimalScale = 0;
      let optimalVMin = new Stitch.Math.Vector(Infinity, Infinity);
      let optimalVMax = new Stitch.Math.Vector(-Infinity, -Infinity);
      for (let a = 0; a < 2 * Math.PI; a += 0.1) {
        let vMin = new Stitch.Math.Vector(Infinity, Infinity);
        let vMax = new Stitch.Math.Vector(-Infinity, -Infinity);
        for (let [k, v] of Object.entries(this.pck)) {
          let p = new Stitch.Math.Vector(v.x, v.y);
          p = p.rotate(a);
          vMin.x = Math.min(vMin.x, p.x - v.r);
          vMin.y = Math.min(vMin.y, p.y - v.r);
          vMax.x = Math.max(vMax.x, p.x + v.r);
          vMax.y = Math.max(vMax.y, p.y + v.r);
        }
        let xDiff = vMax.x - vMin.x;
        let yDiff = vMax.y - vMin.y;
        let s = h / yDiff;
        if (xDiff / yDiff > w / h) s = w / xDiff;
        if (s > optimalScale) {
          optimalAngle = a;
          optimalScale = s;
          optimalVMin = vMin;
          optimalVMax = vMax;
        }
      }
      for (let [k, v] of Object.entries(this.pck)) {
        let p = new Stitch.Math.Vector(v.x, v.y);
        p = p.rotate(optimalAngle);
        let xDiff = optimalVMax.x - optimalVMin.x;
        let yDiff = optimalVMax.y - optimalVMin.y;
        v.x = optimalScale * (p.x - (optimalVMin.x + 0.5 * xDiff)) + x + 0.5 * w;
        v.y = optimalScale * (p.y - (optimalVMin.y + 0.5 * yDiff)) + y + 0.5 * h;
        v.r = optimalScale * v.r;
      }
    }
    getTriData() {
      for (let i = 0; i < this.dt.ts.length; i++) {
        let t = this.dt.ts[i];
        if (t.a in this.pck && t.b in this.pck && t.c in this.pck) this.ts.push([t.a, t.b, t.c]);
      }
    }
    getMinOverlap() {
      if (Object.keys(this.int).length === 0) return -Infinity;
      let minSep = Infinity;
      for (let [k, v] of Object.entries(this.pck)) {
        if (v.l == 'exterior') {
          let currMinSep = Infinity;
          for (let [nk, nv] of Object.entries(this.pck)) {
            if (k != nk && nv.l == 'exterior') {
              let cDist = Stitch.Math.Utils.distance(v.x, v.y, nv.x, nv.y);
              let rSum = v.r + nv.r;
              let currSep = cDist - rSum;
              if (currMinSep > currSep) currMinSep = currSep;
            }
          }
          if (minSep > currMinSep) minSep = currMinSep;
        }
      }
      return minSep;
    }
    getMinRadius() {
      let minRadius = Infinity;
      for (let [k, v] of Object.entries(this.pck)) if (v.r < minRadius) minRadius = v.r;
      return minRadius;
    }
  }




  let bg;
  function generatePattern(small=false) {
    let stitchDensityGridResolutionMm = 0.25;
    let stitchDensityGrid = new Stitch.Math.DensityGrid(wPx, hPx, stitchDensityGridResolutionMm * pixelsPerMm);
    let segmentDensityGridResolutionMm = 0.25;
    let segmentDensityGrid = new Stitch.Math.DensityGrid(wPx, hPx, segmentDensityGridResolutionMm * pixelsPerMm);

    let seeds = [];
    let shapeSegments = [];
    let connectingSegments = [];

    function addShape(polyline) {
      for (let v of polyline.vertices) {
        if (v.x < 0 || v.x > wPx || v.y < 0 || v.y > hPx) return false;
      }
      const shapeVertices = polyline.getRadialDistanceResampled(shapeStitchLengthMm * pixelsPerMm).vertices;
      for (let i = 0; i < (polyline.isClosed ? shapeVertices.length : shapeVertices.length - 1); i++) {
        const p = shapeVertices[i];
        const q = shapeVertices[(i + 1) % shapeVertices.length];
        shapeSegments.push(Stitch.Math.Polyline.fromVectors([p, q], false));
        stitchDensityGrid.addDensityAtPoint(p.x, p.y, 1);
        stitchDensityGrid.addDensityAtPoint(q.x, q.y, 1);
        segmentDensityGrid.addDensityXW(p, q, Infinity);
      }
      seeds.push(polyline.getRadialDistanceResampled(shapeSeedResampleLengthMm * pixelsPerMm).vertices);
      return true;
    }

    function addCircle(x, y, radius, angleSteps = 500) {
      let polyline = new Stitch.Math.Polyline(true);
      for (let i = 0; i < angleSteps; i++) {
        let angle = Stitch.Math.Utils.map(i, 0, angleSteps, 0, 2 * Math.PI);
        polyline.addVertex(x + radius * Math.cos(angle), y + radius * Math.sin(angle));
      }
      return addShape(polyline);
    }

    function addLine(px, py, qx, qy, steps = 500) {
      let p = new Stitch.Math.Vector(px, py);
      let q = new Stitch.Math.Vector(qx, qy);
      let polyline = new Stitch.Math.Polyline(false);
      for (let i = 0; i < steps + 1; i++) {
        let v = p.lerp(q, Stitch.Math.Utils.map(i, 0, steps, 0, 1));
        polyline.addVertex(v.x, v.y);
      }
      return addShape(polyline);
    }

    if (shapeStrategy === 'circle packing') {
      let cp;
      do {
        let dt = new DT(wPx, hPx);
        let count = Math.floor(Stitch.Math.Utils.map(rng.random_dec(), 0, 1, 10, 25));
        for (let i = 0; i < count; i++) dt.add(wPx * rng.random_dec(), hPx * rng.random_dec());
        cp = new CP(dt, function () {
          return Stitch.Math.Utils.map(rng.random_dec(), 0, 1, 100, 300);
        });
      } while (cp.getMinOverlap() < -0.1 || cp.getMinRadius() < 0.05 * Math.min(wPx, hPx) || Object.keys(cp.int).length < 1);
      cp.resize(0, 0, wPx, hPx);


      let reflect = (v, pointOnLine, surfaceNormal) => {
        let vCopy = v.copy()
        vCopy = vCopy.subtract(pointOnLine)
        const surfaceNormalCopy = surfaceNormal.normalized();
        vCopy = vCopy.subtract(surfaceNormalCopy.multiply(2 * vCopy.dot(surfaceNormalCopy)));
        vCopy = vCopy.add(pointOnLine)
        return vCopy
      }

      let normal = Stitch.Math.Vector.fromAngle(rng.random_num(0, 2 * Math.PI));
      // normal = Stitch.Math.Vector.fromAngle(0);
      let count = 0;
      if (small) {
        let n = rng.random_num(1, 8);
        for (let i=0; i<n; i++) {
          let r = rng.random_num(wPx*0.1, wPx*0.2);
          let x = rng.random_num(r, wPx - r);
          let y = rng.random_num(r, hPx - r);
          addCircle(x, y, r);
        }
      } else {
          for (let [k, v] of Object.entries(cp.pck)) {
            let rMult = v.l === 'exterior' ? 1 : 1.5;
            if (rng.random_dec() > 0.2 && (new Stitch.Math.Vector(v.x, v.y)).distance(new Stitch.Math.Vector(0.5 * wPx, 0.5 * hPx)) > v.r) {
              let [n1x, n1y, n2x, n2y] = [rng.random_num(-nudgeAmountPx, nudgeAmountPx), rng.random_num(-nudgeAmountPx, nudgeAmountPx), rng.random_num(-nudgeAmountPx, nudgeAmountPx), rng.random_num(-nudgeAmountPx, nudgeAmountPx)];
              if (rng.random_dec() > 0.4) {
                n1x = 0;
                n1y = 0;
                // n2x = 0;
                // n2y = 0;
              }
              if (addCircle(v.x + n1x, v.y + n1y, rMult * v.r)) count++;
              if (rng.random_dec() > 0.2) {
                let ref = reflect(new Stitch.Math.Vector(v.x, v.y), new Stitch.Math.Vector(0.5 * wPx, 0.5 * hPx), normal);
                if (addCircle(ref.x, ref.y, rMult * v.r)) count++;
              }
            }
          }
          if (count <= 8) {
            normal = Stitch.Math.Vector.fromAngle(rng.random_num(0, 2 * Math.PI));
            for (let [k, v] of Object.entries(cp.pck)) {
              let rMult = v.l === 'exterior' ? 1 : 1.5;
              if (rng.random_dec() > 0.2 && (new Stitch.Math.Vector(v.x, v.y)).distance(new Stitch.Math.Vector(0.5 * wPx, 0.5 * hPx)) > v.r) {
                let [n1x, n1y, n2x, n2y] = [rng.random_num(-nudgeAmountPx, nudgeAmountPx), rng.random_num(-nudgeAmountPx, nudgeAmountPx), rng.random_num(-nudgeAmountPx, nudgeAmountPx), rng.random_num(-nudgeAmountPx, nudgeAmountPx)];
                if (rng.random_dec() > 0.4) {
                  n1x = 0;
                  n1y = 0;
                  // n2x = 0;
                  // n2y = 0;
                }
                addCircle(v.x + n1x, v.y + n1y, rMult * v.r);
                count++;
                if (rng.random_dec() > 0.2) {
                  let ref = reflect(new Stitch.Math.Vector(v.x, v.y), new Stitch.Math.Vector(0.5 * wPx, 0.5 * hPx), normal);
                  addCircle(ref.x, ref.y, rMult * v.r);
                  count++;
                }
              }
            }
        }
      }
    } else if (shapeStrategy === 'lines') {
      let countLines = rng.random_int(10, 15)
      if (small) countLines /= 2
      let r = rng.random_dec();
      for (let i = 0; i < countLines; i++) {
        let p = new Stitch.Math.Vector(rng.random_num(0.05 * wPx, 0.95 * wPx), rng.random_num(0.05 * hPx, 0.95 * hPx));
        let q = new Stitch.Math.Vector(rng.random_num(0.05 * wPx, 0.95 * wPx), rng.random_num(0.05 * hPx, 0.95 * hPx));
        while (p.distance(q) < 100) {
          q = new Stitch.Math.Vector(rng.random_num(0.05 * wPx, 0.95 * wPx), rng.random_num(0.05 * hPx, 0.95 * hPx));
        }
        addLine(
          p.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx), p.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx),
          q.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx), q.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx)
        );
        if (!small) {
          if (r < 0.25) {
            addLine(
              wPx - (p.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx)), hPx - (p.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx)),
              (q.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx)), hPx - (q.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx))
            );
          } else if (r < 0.5) {
            addLine(
              (p.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx)), hPx - (p.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx)),
              hPx - (q.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx)), hPx - (q.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx))
            );
          } else {
            addLine(
              wPx - (p.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx)), hPx - (p.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx)),
              hPx - (q.x + rng.random_num(-nudgeAmountPx, nudgeAmountPx)), hPx - (q.y + rng.random_num(-nudgeAmountPx, nudgeAmountPx))
            );
          }
        }
      }
    }

    // find the connecting segments
    for (let i = 0; i < seeds.length; i++) {
      for (let j = 0; j < seeds[i].length; j++) {
        let p = seeds[i][j];
        for (let k = i + 1; k < seeds.length; k++) {
          for (let l = 0; l < seeds[k].length; l++) {
            let q = seeds[k][l];
            let d = p.distance(q);
            if (d > minConnectingStitchLengthMm * pixelsPerMm && d < maxConnectingStitchLengthMm * pixelsPerMm) {
              connectingSegments.push(Stitch.Math.Polyline.fromVectors([p, q], false));
            }
          }
        }
      }
    }

    // shuffle the connecting segments
    connectingSegments = Stitch.Math.Utils.getShuffledArray(connectingSegments, rng);

    // remove segments that would cause density issues
    // always keep the original shape segments and put them at the beginning of the array to give them priority
    let filteredSegments = [...shapeSegments];
    for (let segment of connectingSegments) {
      if (
        segmentDensityGrid.getDensityAtPoint(segment.vertices[0].x, segment.vertices[0].y) <= stitchDensityCutoff &&
        segmentDensityGrid.getDensityAtPoint(segment.vertices[1].x, segment.vertices[1].y) <= stitchDensityCutoff
      ) {
        if (segmentDensityGrid.addDensityXW(segment.vertices[0], segment.vertices[1], segmentDensityCutoff)) {
          stitchDensityGrid.addDensityAtPoint(segment.vertices[0].x, segment.vertices[0].y, 1);
          stitchDensityGrid.addDensityAtPoint(segment.vertices[1].x, segment.vertices[1].y, 1);
          filteredSegments.push(segment);
        }
      }
    }

    class NonResampledRun {
      constructor(polyline) {
        this.polyline = polyline;
      }

      getStitches() {
        return this.polyline.vertices;
      }
    }

    let pattern = new Stitch.Core.Pattern(wPx, hPx);
    let thread;
    if (palette === 'black on white') {
      thread = pattern.addThread(0, 0, 0);
      bg = 'white';
      document.body.setAttribute('style', 'background-color: white');
    } else {
      thread = pattern.addThread(255, 255, 255);
      bg = 'black';
      document.body.setAttribute('style', 'background-color: black');
    }
    let joinedPolylines = Stitch.Optimize.joinPolylines(filteredSegments, maxJoinDistanceMm * pixelsPerMm);
    for (let joinedPolyline of joinedPolylines) {
      if (joinedPolyline.vertices.length > 3) {
        thread.addRun(new NonResampledRun(joinedPolyline));
      }
    }

    return pattern;
  }

  let pattern = generatePattern();

  let svg;
  function drawSvg() {
    if (svg) svg.remove();
    svg = Stitch.Graphics.getSvg(pattern, window.innerWidth, window.innerHeight, { pixelMultiplier: widthMm / wPx });
    const windowAsp = window.innerWidth / window.innerHeight;
    const strokeWidth = windowAsp > wPx / hPx ? 0.003 * window.innerHeight : 0.003 * window.innerWidth * hPx / wPx;
    svg.setAttribute('style', `margin: auto; position: absolute; inset: 0; background-color: ${bg}; stroke-width: ${strokeWidth};`);
    let vw = svg.getAttribute('viewBox').split(' ')[2];
    let vh = svg.getAttribute('viewBox').split(' ')[3];
    console.log(vw, vh);
    svg.setAttribute('viewBox', `${-svgMarginMultiplier * vw} ${-svgMarginMultiplier * vh} ${(1 + 2 * svgMarginMultiplier) * vw} ${(1 + 2 * svgMarginMultiplier) * vh}`);
    document.body.append(svg);
  }
  window.addEventListener('load', drawSvg);
  window.addEventListener('resize', Stitch.Browser.Utils.debounce(() => drawSvg(), 1));


  function saveSvg(svgEl, name) {
    svgEl.setAttribute("xmlns", "http://www.w3.org/2000/svg");
    var svgData = svgEl.outerHTML;
    var preface = '<?xml version="1.0" standalone="no"?>\r\n';
    var svgBlob = new Blob([preface, svgData], {type:"image/svg+xml;charset=utf-8"});
    var svgUrl = URL.createObjectURL(svgBlob);
    var downloadLink = document.createElement("a");
    downloadLink.href = svgUrl;
    downloadLink.download = name;
    document.body.appendChild(downloadLink);
    downloadLink.click();
    document.body.removeChild(downloadLink);
  }

  window.addEventListener('keydown', (e) => {
    if (e.code === 'KeyD') {
      Stitch.IO.write(pattern, wPx / pixelsPerMm, hPx / pixelsPerMm, `${rng.hash}.dst`);
    } else if (e.code === 'KeyP') {
      Stitch.IO.write(pattern, wPx / pixelsPerMm, hPx / pixelsPerMm, `${rng.hash}.pes`);
    } else if (e.code === 'Space') {
      widthMm = Stitch.Math.Utils.inToMm(2);
      pixelsPerMm = wPx / widthMm;
      pattern = generatePattern(small=true);
      drawSvg();
    } else if (e.code === 'KeyS') {
      saveSvg(svg, `${rng.hash}.svg`);
    }
  });
}

